  const browseTargets=()=>S.browse.scopeEmpty?[]:bucket().filter(p=>S.browse.platformIds.includes(p.id));
  function seedBrowseSelection(){if(S.browse.initialized)return;const p=selected();if(!p)return;S.browse.platformIds=[p.id];S.browse.draftPlatformIds=[...S.browse.platformIds];S.browse.scopeEmpty=!p;S.browse.draftAll=false;S.browse.initialized=true;}
